Demo.Run<object[]>(async demo =>
{
    await demo.Store.WriteAsync(
    [
        Demo.Error("a1b2c3d4e5f60718", Demo.Now.AddHours(-30), trace: "00-old"),
        Demo.Error("a1b2c3d4e5f60718", Demo.Now.AddHours(-2), trace: "00-mid"),
        Demo.Error("a1b2c3d4e5f60718", Demo.Now.AddMinutes(-5), trace: "00-new")
    ]);

    var result = await demo.Reader.GetIssueAsync("a1b2c3d4e5f60718", null, trace: "00-old", withStack: false);
    var detail = result.Data!;

    return [detail.Message!, detail.StackHidden, detail.Found!, string.Join(", ", detail.Samples.Select(s => s.TraceId))];
});

