services.AddOSDiagnosticsData(o =>
{
    o.ScanLimit = 20000;
    o.MaxIssues = 200;
    o.SampleLimit = 50;
    o.NewHours = 48;
    o.Table = "AppErrors";
});

services.AddOSDiagnostics(o => o.AppCode = "shop");
services.AddOSSqlite<DiagnosticsDb>(o =>
{
    o.Path = "data/errors.db";
    o.Key = keyFromVault;
});
services.AddOSDiagnosticsData(o => o.RetentionDays = 14);

Demo.Run(async demo =>
{
    var message = "Login failed for sara@example.com, Password=hunter2; card 6037-9912-3456-7893, code 0012345679";
