Demo.Run<string?[]>(async demo =>
{
    await demo.Store.WriteAsync(
    [
        Demo.Error("a1b2c3d4e5f60718", Demo.Now, "Order 1234567890 failed at line 42", trace: "t-1"),
        Demo.Error("a1b2c3d4e5f60718", Demo.Now, "Token expired at 1760000000", trace: "t-2")
    ]);

    var rows = await demo.UseDbAsync(db => db.Entity<ErrorEntry>().OrderBy(e => e.Id).Select(e => e.Message).ToListAsync());

    return [.. rows];
});

Demo.Run<object[]>(async demo =>
{
    await demo.Store.WriteAsync(
    [
        Demo.Error("a1b2c3d4e5f60718", Demo.Now.AddDays(-45)),
        Demo.Error("a1b2c3d4e5f60718", Demo.Now.AddDays(-31)),
        Demo.Error("a1b2c3d4e5f60718", Demo.Now.AddDays(-2))
    ]);

    var result = await demo.UseDbAsync(db => db.PurgeErrorsAsync(Demo.Now.AddDays(-30)));
    var left = await demo.UseDbAsync(db => db.Entity<ErrorEntry>().CountAsync());

    return [result.Code!, result.Data, left];
});

